import Events from "./events.js";
import Path from "./path.js";
import { updateDependencies, updateVersion } from "./services/hmr.js";
import { watchFiles } from "./services/fs.js";
export default class FSWatcher {
    events = new Events();
    options;
    paused = false;
    constructor(options) {
        this.options = options;
    }
    /** Add a listener to an event */
    addEventListener(type, listener, options) {
        this.events.addEventListener(type, listener, options);
        return this;
    }
    /** Dispatch an event */
    dispatchEvent(event) {
        return this.events.dispatchEvent(event);
    }
    /** Start the file watcher */
    async start() {
        const { root, ignore, debounce, dependencies } = this.options;
        const rootPath = Path.create(root);
        const watcher = watchFiles(rootPath.toString());
        const changes = new Set();
        let timer = undefined;
        let runningCallback = false;
        await this.dispatchEvent({ type: "start" });
        const callback = async () => {
            // If the callback is already running, debounce the next call
            if (runningCallback) {
                clearTimeout(timer);
                setTimeout(callback, debounce ?? 100);
                return;
            }
            runningCallback = true;
            const files = new Set(changes);
            changes.clear();
            if (!files.size) {
                runningCallback = false;
                return;
            }
            try {
                const result = await this.dispatchEvent({
                    type: "change",
                    files: files,
                });
                if (false === result) {
                    runningCallback = false;
                    return watcher.close();
                }
            }
            catch (err) {
                await this.dispatchEvent({ type: "error", error: err });
            }
            finally {
                runningCallback = false;
            }
            // New changes detected while running the callback
            if (changes.size) {
                void callback();
            }
        };
        for await (const changedPaths of watcher) {
            const paths = new Set();
            updateVersion();
            for (const path of changedPaths.map((p) => Path.create(p))) {
                const normalized = Path.create(path);
                if (!normalized.belongsTo(rootPath)) {
                    continue;
                }
                const full = normalized.url.href;
                normalized.removeBase(rootPath);
                // Filter ignored paths
                const isIgnored = ignore?.some((condition) => typeof condition === "string"
                    ? normalized.belongsTo(condition)
                    : condition(normalized.toString()));
                if (isIgnored)
                    continue;
                paths.add(normalized.toString());
                for (const dep of updateDependencies(full)) {
                    const normalizedDep = Path.create(dep);
                    if (normalizedDep.belongsTo(rootPath)) {
                        paths.add(normalizedDep.removeBase(rootPath).toString());
                    }
                }
            }
            if (!paths.size) {
                continue;
            }
            paths.forEach((path) => {
                changes.add(path);
                // The file has dependencies
                for (const [file, deps] of Object.entries(dependencies ?? {})) {
                    const isDependent = deps.some((dep) => Path.create(dep).toString() === path);
                    if (isDependent) {
                        changes.add(Path.create(file).toString());
                    }
                }
            });
            // Only run the callback if it is not already running
            if (!runningCallback) {
                // Debounce
                clearTimeout(timer);
                timer = setTimeout(callback, debounce ?? 100);
            }
        }
    }
}
export class SiteWatcher {
    site;
    events = new Events();
    constructor(site) {
        this.site = site;
    }
    /** Add a listener to an event */
    addEventListener(type, listener, options) {
        this.events.addEventListener(type, listener, options);
        return this;
    }
    /** Dispatch an event */
    dispatchEvent(event) {
        return this.events.dispatchEvent(event);
    }
    /** Start the watcher */
    async start() {
        await this.dispatchEvent({ type: "start" });
        this.site.addEventListener("afterUpdate", (event) => {
            const files = new Set([
                ...event.pages.map((page) => page.outputPath),
                ...event.staticFiles.map((file) => file.outputPath),
            ]);
            void this.dispatchEvent({ type: "change", files });
        });
    }
}
